from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAdminUser
from rest_framework import status
from django.apps import apps
from cacheops import invalidate_model

class ModelCachePurgeView(APIView):
    # Only platform infrastructure administrators may trigger global model cache invalidation
    permission_classes = [IsAdminUser]

    def post(self, request, model_name: str):
        try:
            model_cls = apps.get_model('crm', model_name)
        except LookupError:
            return Response({'error': 'Invalid model'}, status=status.HTTP_400_BAD_REQUEST)

        invalidate_model(model_cls)
        return Response({'status': 'cache_purged', 'model': model_name})
